package com.zafiro.wxentry.kernel;
import java.util.*;import java.nio.file.*;
public final class SnsLocalTimesTest {
 static int checks;static void ok(boolean b){checks++;if(!b)throw new AssertionError("times "+checks);}static void bad(Runnable r){try{r.run();throw new AssertionError("Must reject");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args)throws Exception{
  String owner=RedPacketRuntime.hash("wxid_owner_a"),id=RedPacketRuntime.hash("event");SnsLocalTimes data=new SnsLocalTimes(owner);Random random=new Random(262);Set<Long> seen=new HashSet<Long>();
  for(int i=0;i<1000;i++){long value=SnsLocalTimes.sample(1000,2000,random);ok(value>=1000&&value<=2000);seen.add(value);}ok(seen.size()>500);ok(SnsLocalTimes.sample(7,7,random)==7);bad(()->SnsLocalTimes.sample(9,8,random));bad(()->SnsLocalTimes.sample(-1,8,random));
  long at=data.resolve(id,1000,2000,random);ok(data.resolve(id,1000,9000,random)==at);String encoded=data.encode();data=SnsLocalTimes.decode(encoded,owner);ok(data.resolve(id,1000,10000,random)==at);ok(data.values.get(id).created==2000);bad(()->SnsLocalTimes.decode(encoded,RedPacketRuntime.hash("other")));bad(()->SnsLocalTimes.decode(encoded+id+"|1|2|9\n",owner));bad(()->SnsLocalTimes.decode(encoded+id+"|1000|2000|1000\n",owner));
  final String post="wxid_owner_a~1";SnsLocalData.Person person=new SnsLocalData.Person("wxid_friend","好友");SnsLocalData.Comment comment=new SnsLocalData.Comment("local_11111111111111111111111111111111",person,"评论");SnsLocalData records=SnsLocalData.empty().likes(post,Arrays.asList(person),2000).addComments(post,Arrays.asList(comment),2000);Map<String,Long> published=Collections.singletonMap(post,1000L);Path dir=Paths.get(args[0],"sns-time-store");Files.createDirectories(dir);Kernel.WXDIR=dir.toString()+java.io.File.separator;
  Map<String,Long> times=SnsLocalTimesStore.resolve(Kernel.account,records,published);String like=SnsLocalTimes.event(post,person.id,null),text=SnsLocalTimes.event(post,person.id,comment.localId);ok(times.size()==2&&!like.equals(text));ok(times.get(like)>=1000&&times.get(like)<=2000);ok(times.get(text)>=1000&&times.get(text)<=2000);ok(SnsLocalTimesStore.resolve(Kernel.account,records.edit(post,comment.localId,"修改",9000),published).equals(times));
  byte[] saved=Files.readAllBytes(dir.resolve("moments.local.times."+owner.substring(0,16)));Kernel.account="wxid_other";ok(SnsLocalTimesStore.resolve("wxid_owner_a",records,published).isEmpty());Kernel.account="wxid_owner_a";Kernel.edition="free";ok(SnsLocalTimesStore.resolve(Kernel.account,records,published).isEmpty());Kernel.edition="vip";ok(Arrays.equals(saved,Files.readAllBytes(dir.resolve("moments.local.times."+owner.substring(0,16)))));
  ok(SnsLocalTimesStore.resolve(Kernel.account,records.clear(),published).isEmpty());ok(SnsLocalTimes.decode(RedPacketRuntime.read(Kernel.WXDIR+"moments.local.times."+owner.substring(0,16)),owner).values.isEmpty());
  System.out.println("PASS "+checks+" per-interaction time interval, stable reload/edit, independent identities, ownership, paid gating and cleanup checks");
 }
}
